/**
 * A `fetch` that answers the recorded requests and fails every other one as an unreachable network
 * would — so a loader that asks for anything else than what was recorded does not load.
 *
 * @param seen collects every URL asked for, answered or not.
 */
export function replayTrial(seen: string[] = []): (url: string) => Promise<Response> {
  return async (url) => {
    seen.push(url);
    const recorded = TRIAL_EXCHANGES.find((exchange) => exchange.url === url);
    if (recorded === undefined) throw new TypeError("Failed to fetch");
    return new Response(recorded.body, { status: recorded.status });
  };
}
